#include <gtest/gtest.h>
#include "AssemblerTestsUtils.h"

using namespace assemblerTests;

TEST(IMMEDIATE, VALID_I32_MAX) {
    ASSERT_NO_ASSEMBLER_ERROR("push i32 #2147483647");
}

TEST(IMMEDIATE, VALID_I32_MIN) {
    ASSERT_NO_ASSEMBLER_ERROR("push i32 #-2147483648");
}

TEST(IMMEDIATE, VALID_UI32_MAX) {
    ASSERT_NO_ASSEMBLER_ERROR("push ui32 #4294967295");
}

TEST(IMMEDIATE, VALID_UI32_MIN) {
    ASSERT_NO_ASSEMBLER_ERROR("push ui32 #0");
}

TEST(IMMEDIATE, VALID_I64_MAX) {
    ASSERT_NO_ASSEMBLER_ERROR("push i64 #9223372036854775807");
}

TEST(IMMEDIATE, VALID_I64_MIN) {
    ASSERT_NO_ASSEMBLER_ERROR("push i64 #-9223372036854775808");
}

TEST(IMMEDIATE, VALID_UI64_MAX) {
    ASSERT_NO_ASSEMBLER_ERROR("push ui64 #18446744073709551615");
}

TEST(IMMEDIATE, VALID_UI64_MIN) {
    ASSERT_NO_ASSEMBLER_ERROR("push ui64 #0");
}

TEST(IMMEDIATE, VALID_F32_MAX) {
    ASSERT_NO_ASSEMBLER_ERROR("push f32 #340282346638528859811704183484516925440.0");
}

TEST(IMMEDIATE, VALID_F32_MIN) {
    ASSERT_NO_ASSEMBLER_ERROR("push f32 #-340282346638528859811704183484516925440.0");
}

TEST(IMMEDIATE, VALID_F64_MAX) {
    ASSERT_NO_ASSEMBLER_ERROR("push f64 #" + std::to_string(std::numeric_limits<double>::max()));
}

TEST(IMMEDIATE, VALID_F64_MIN) {
    ASSERT_NO_ASSEMBLER_ERROR("push f64 #" + std::to_string(std::numeric_limits<double>::min()));
}

TEST(IMMEDIATE, INVALID_I32_MAX) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push i32 #2147483648");
}

TEST(IMMEDIATE, INVALID_I32_MIN) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push i32 #-2147483649");
}

TEST(IMMEDIATE, INVALID_I32_DECIMAL) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push i32 #-1.5");
}

TEST(IMMEDIATE, INVALID_UI32_MAX) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push ui32 #4294967296");
}

TEST(IMMEDIATE, INVALID_UI32_MIN) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push ui32 #-1");
}

TEST(IMMEDIATE, INVALID_UI32_DECIMAL) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push ui32 #1.5");
}

TEST(IMMEDIATE, INVALID_I64_MAX) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push i64 #9223372036854775808");
}

TEST(IMMEDIATE, INVALID_I64_MIN) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push i64 #-9223372036854775809");
}

TEST(IMMEDIATE, INVALID_I64_DECIMAL) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push i64 #1.5");
}

TEST(IMMEDIATE, INVALID_UI64_MAX) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push ui64 #18446744073709551616");
}

TEST(IMMEDIATE, INVALID_UI64_MIN) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push ui64 #-1");
}

TEST(IMMEDIATE, INVALID_UI64_DECIMAL) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push ui64 #1.5");
}

TEST(IMMEDIATE, INVALID_F32_MAX) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push f32 #999999999999999999999999999999999999999.0");
}

TEST(IMMEDIATE, INVALID_F32_MIN) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push f32 #-999999999999999999999999999999999999999.0");
}

TEST(IMMEDIATE, INVALID_F64_MAX) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push f64 #.0");
}

TEST(IMMEDIATE, INVALID_F64_MIN) {
    ASSERT_THROWS_ASSEMBLER_ERROR("push f64 #-.0");
}